#!/bin/bash
set -euo pipefail

# This script is called by Dune to build and copy Skia and its modules.
# It reads arguments from files generated by the OCaml configurator.
# IMPORTANT: This script is executed from the 'vendor/' directory.
# All paths referring to the Skia source tree MUST be prefixed with 'skia/'.

# Arguments passed from Dune via files (paths are relative to vendor/dune file)
OS_NAME=$(cat os.txt)
ARCH_NAME=$(cat arch.txt)
LIB_EXT=$(cat lib_ext.txt)

# Environment variable to control shaping
SKIA_ENABLE_SHAPING="${SKIA_ENABLE_SHAPING:-}" # Default to empty string if not set

# --- Step 1: Prepare Ninja targets and copy lists ---
NINJA_TARGETS="skia modules/skottie modules/svg"
COPY_LIBS_BASE="libskia libsvg libskottie" # These are just names, not paths yet

if [[ "$SKIA_ENABLE_SHAPING" = "1" || "$SKIA_ENABLE_SHAPING" = "yes" ]]; then
  echo "SKIA_ENABLE_SHAPING is enabled. Including SkShaper."
  NINJA_TARGETS="$NINJA_TARGETS modules/skshaper"
  COPY_LIBS_BASE="$COPY_LIBS_BASE libskshaper"
else
  echo "SKIA_ENABLE_SHAPING is disabled. Excluding SkShaper."
fi

# --- Step 2: Build Skia using Ninja ---
ninja -C skia/out/"$OS_NAME"/"$ARCH_NAME" $NINJA_TARGETS

# --- Step 3: Copy compiled libraries and headers to prefix/skia/ ---
echo "Copying compiled artifacts to prefix/skia/..."

# Create the main installation root for Skia (relative to vendor/)
SKIA_INSTALL_ROOT="prefix/skia"
mkdir -p "${SKIA_INSTALL_ROOT}/lib"
mkdir -p "${SKIA_INSTALL_ROOT}/include"
mkdir -p "${SKIA_INSTALL_ROOT}/modules" # This is important for module headers

# Copy libraries
LIBS_CP_COMMAND=""
for lib_name in $COPY_LIBS_BASE; do
  # Libraries are in skia/out/... relative to vendor/
  LIBS_CP_COMMAND+="cp skia/out/$OS_NAME/$ARCH_NAME/${lib_name}.$LIB_EXT ${SKIA_INSTALL_ROOT}/lib/ && "
done
eval "${LIBS_CP_COMMAND% && }"

# --- Header Copying ---
# Copy the entire 'include' directory contents from skia/include/ to prefix/skia/include/
echo "Copying core Skia headers (skia/include/ -> prefix/skia/include/)..."
cp -r skia/include/* "${SKIA_INSTALL_ROOT}/include/"

# Copy module headers, preserving their path structure under 'modules/'.
# This handles paths like "skia/modules/svg/include/SkSVGTypes.h"
echo "Copying module headers (skia/modules/*/include/ -> prefix/skia/modules/*/include/)..."
# Use find starting from skia/modules/
find skia/modules/ -maxdepth 2 -type d -name "include" -print0 | while IFS= read -r -d $'\0' module_include_dir_path; do
  # module_include_dir_path will be like "skia/modules/svg/include"
  
  # Remove the leading "skia/" to get the relative path from the Skia root
  # This gives "modules/svg/include"
  relative_path_from_skia_root="${module_include_dir_path#skia/}"

  # The full destination directory path
  dest_dir="${SKIA_INSTALL_ROOT}/${relative_path_from_skia_root}"

  mkdir -p "$dest_dir"
  # Copy the contents of the 'include' directory
  cp -r "${module_include_dir_path}"/* "$dest_dir"/
done